const crypto = require('crypto');

class SecureRotationLogger {
  constructor() {
    this.rotationLog = [];
  }

  logRotationEvent(credentialType, environment, status, metadata = {}) {
    const event = {
      timestamp: new Date().toISOString(),
      credentialType,
      environment,
      status,
      referenceId: this.generateReferenceId(credentialType),
      metadata: {
        ...metadata,
        // Never include the actual value
        valueLength: metadata.value ? metadata.value.length : undefined,
        valueHash: metadata.value ? this.hashValue(metadata.value) : undefined
      }
    };

    this.rotationLog.push(event);
    this.persistLog(event);

    return event.referenceId;
  }

  generateReferenceId(credentialType) {
    const prefix = credentialType.toLowerCase().replace(/_/g, '-');
    const random = crypto.randomBytes(4).toString('hex');
    return `${prefix}-${random}`;
  }

  hashValue(value) {
    // Create a secure hash for verification without exposing the value
    return crypto.createHash('sha256').update(value).digest('hex');
  }

  persistLog(event) {
