// Validate required environment variables
const validateSecrets = () => {
  const missingSecrets = [];

  // Always required
  const alwaysRequired = ['JWT_SECRET'];

  // Production-only requirements
  const productionRequired = [
    'ENCRYPTION_KEY',
    'DATABASE_URL',
    'AWS_ACCESS_KEY_ID',
    'AWS_SECRET_ACCESS_KEY'
  ];

  alwaysRequired.forEach(varName => {
    if (!process.env[varName]) {
      missingSecrets.push(varName);
    }
  });

  if (process.env.NODE_ENV === 'production') {
    productionRequired.forEach(varName => {
      if (!process.env[varName]) {
        missingSecrets.push(varName);
      }
    });
  }

  if (missingSecrets.length > 0) {
    throw new Error(`Missing required secrets: ${missingSecrets.join(', ')}`);
  }
};

// Validate secrets on startup
validateSecrets();

// Security: Mask secrets in logs
config.getMaskedConfig = () => {
  const masked = { ...config };

  // Mask sensitive values
  if (masked.jwtSecret) masked.jwtSecret = '***MASKED***';
  if (masked.encryptionKey) masked.encryptionKey = '***MASKED***';
  if (masked.database.url) masked.database.url = masked.database.url.replace(/:[^:]*@/, ':***MASKED***@');
  if (masked.aws.secretAccessKey) masked.aws.secretAccessKey = '***MASKED***';
  if (masked.apiKeys.stripe) masked.apiKeys.stripe = '***MASKED***';
  if (masked.apiKeys.anthropic) masked.apiKeys.anthropic = '***MASKED***';
  if (masked.logging.logfireToken) masked.logging.logfireToken = '***MASKED***';

