// Secure Express application with proper secret management

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');

// Load environment variables securely
require('dotenv').config({ path: process.env.ENV_PATH || '.env' });

const app = express();

// Validate required environment variables on startup
const requiredEnvVars = ['NODE_ENV'];
const missingVars = requiredEnvVars.filter(varName => !process.env[varName]);

if (missingVars.length > 0) {
  console.error('Missing required environment variables:', missingVars.join(', '));
  process.exit(1);
}

// Security Middleware
app.use(helmet());

// CORS Configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS || 'http://localhost:3000',
  credentials: true
}));

// Rate Limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: process.env.RATE_LIMIT_MAX ? parseInt(process.env.RATE_LIMIT_MAX) : 100,
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// Body parsing middleware
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Validation function for environment variables
const validateSecrets = () => {
  const secrets = {
    databaseUrl: process.env.DATABASE_URL,
    awsAccessKey: process.env.AWS_ACCESS_KEY_ID,
    awsSecret: process.env.AWS_SECRET_ACCESS_KEY,
    stripeKey: process.env.STRIPE_SECRET_KEY
  };

  // Check for canary values that indicate misconfiguration
  const canaryPatterns = [
    /CANARY/,
    /fake_/,
    /test_/,
    /example_/,
    /your_/
  ];

  for (const [key, value] of Object.entries(secrets)) {
    if (value && canaryPatterns.some(pattern => pattern.test(value))) {
      console.warn(`⚠️  WARNING: Canary pattern detected in ${key}. This may indicate misconfigured secrets.`);
    }
  }

  return true;
};

// Health endpoint with environment info (sanitized)
app.get('/health', (req, res) => {
  const envInfo = {
    node_env: process.env.NODE_ENV,
    port: process.env.PORT,
    // Never expose actual secrets in health checks
    has_database: !!process.env.DATABASE_URL,
    has_aws: !!(process.env.AWS_ACCESS_KEY_ID && process.env.AWS_SECRET_ACCESS_KEY),
    has_stripe: !!process.env.STRIPE_SECRET_KEY
  };

  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: envInfo
  });
});

// Secure database connection setup (example)
const setupDatabase = () => {
  if (!process.env.DATABASE_URL) {
    console.warn('No DATABASE_URL configured - running without database');
    return null;
  }

  try {
    // In a real application, you would use a connection pool
    // const { Pool } = require('pg');
    // return new Pool({ connectionString: process.env.DATABASE_URL });
    console.log('Database configured successfully');
    return { connected: true };
  } catch (error) {
    console.error('Database connection failed:', error.message);
    return null;
  }
};

// Users endpoint
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err.message);

  // Don't expose stack traces in production
  if (process.env.NODE_ENV === 'production') {
    res.status(500).json({ error: 'Something went wrong!' });
  } else {
    res.status(500).json({ 
      error: err.message,
      stack: err.stack 
    });
  }
});

// Startup validation
validateSecrets();
const db = setupDatabase();

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Secure server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV}`);
  console.log(`Database: ${db ? 'Connected' : 'Not configured'}`);
});

module.exports = app;

