// Security middleware for Express.js
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

// Security headers
const securityHeaders = (req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  res.setHeader('Permissions-Policy', 'geolocation=(), microphone=(), camera=()');
  next();
};

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});

module.exports = { securityHeaders, limiter };

// Input validation and sanitization middleware
const { body, query, validationResult } = require('express-validator');

// Validate and sanitize all incoming requests
const validateRequest = (req, res, next) => {
  // Basic input sanitization
  Object.keys(req.query).forEach(key => {
    if (typeof req.query[key] === 'string') {
      req.query[key] = req.query[key].replace(/[<>\"\']/g, '');
    }
  });

  Object.keys(req.params).forEach(key => {
    if (typeof req.params[key] === 'string') {
      req.params[key] = req.params[key].replace(/[<>\"\']/g, '');
    }
  });

  next();
};

// Specific validation for user endpoints
const validateUserInput = [
  query('id').optional().isInt().withMessage('ID must be an integer'),
  query('email').optional().isEmail().normalizeEmail().withMessage('Invalid email format'),
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        errors: errors.array(),
        message: 'Validation failed' 
      });
    }
    next();
  }
];

module.exports = { validateRequest, validateUserInput };

