// Secure secrets management utility
const { config } = require('dotenv');
const { z } = require('zod');

// Schema for environment validation
const environmentSchema = z.object({
  NODE_ENV: z.enum(['development', 'production', 'test']).default('development'),
  PORT: z.string().transform(Number).default('3000'),

  // Database (optional in development)
  DATABASE_URL: z.string().url().optional(),

  // API Keys - validate format but don't log values
  AWS_ACCESS_KEY_ID: z.string().min(20).optional(),
  AWS_SECRET_ACCESS_KEY: z.string().min(40).optional(),
  ANTHROPIC_API_KEY: z.string().min(30).optional(),
  STRIPE_SECRET_KEY: z.string().min(30).optional(),
  LOGFIRE_TOKEN: z.string().min(20).optional(),

  // Security secrets
  JWT_SECRET: z.string().min(32),
  SESSION_SECRET: z.string().min(32)
});

class SecretsManager {
  constructor() {
    this.secrets = {};
    this.loaded = false;
  }

  load() {
    if (this.loaded) return this.secrets;

    // Load environment variables safely
    const { parsed, error } = config();

    if (error) {
      throw new Error(`Failed to load environment: ${error.message}`);
    }

    try {
      this.secrets = environmentSchema.parse(parsed || process.env);
      this.loaded = true;

      // Mask sensitive values in logs
      this.logSafeConfig();

      return this.secrets;
    } catch (validationError) {
      console.error('Environment validation failed:', validationError.errors);
      throw new Error('Invalid environment configuration');
    }
  }

  get(key) {
    if (!this.loaded) this.load();
    return this.secrets[key];
  }

  // Safe logging that masks sensitive values
  logSafeConfig() {
    const safeConfig = { ...this.secrets };

    // Mask sensitive values
    const sensitiveKeys = [
      'AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY',
      'ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY',
      'LOGFIRE_TOKEN', 'JWT_SECRET', 'SESSION_SECRET',
      'DATABASE_URL'
    ];

    sensitiveKeys.forEach(key => {
      if (safeConfig[key]) {
        safeConfig[key] = '***MASKED***';
      }
    });

    console.log('🔐 Loaded environment configuration:', safeConfig);
  }

  // Check if we're missing required secrets
  validateForEnvironment() {
    const secrets = this.load();
    const { NODE_ENV } = secrets;

    if (NODE_ENV === 'production') {
      const required = ['JWT_SECRET', 'SESSION_SECRET'];
      const missing = required.filter(key => !secrets[key]);

      if (missing.length > 0) {
        throw new Error(`Missing required secrets for production: ${missing.join(', ')}`);
      }
    }
  }
}

// Singleton instance
module.exports = new SecretsManager();

