const crypto = require('crypto');

class RotationTracker {
  constructor() {
    this.rotationNeeded = new Set();
    this.rotationHistory = new Map();
  }

  // Safely identify variables that need rotation without exposing values
  identifyRotationNeeded(envContent) {
    const lines = envContent.split('\n');
    const sensitivePatterns = [
      /API.*KEY/i,
      /SECRET/i,
      /TOKEN/i,
      /PASSWORD/i,
      /ACCESS.*KEY/i,
      /DATABASE.*URL/i,
      /PRIVATE.*KEY/i,
      /AUTH.*KEY/i
    ];

    lines.forEach(line => {
      if (line.trim() && !line.startsWith('#')) {
        const [key] = line.split('=');

        // Check if this looks like a sensitive variable
        if (key && sensitivePatterns.some(pattern => pattern.test(key))) {
          this.rotationNeeded.add(key.trim());
          console.log(`🔄 Rotation recommended for: ${key.trim()}`);
        }
      }
    });

    return Array.from(this.rotationNeeded);
  }

  // Generate secure tracking hash (not the actual value)
  generateTrackingHash(variableName, envContent) {
    const lines = envContent.split('\n');
    for (const line of lines) {
      if (line.startsWith(variableName + '=')) {
        const value = line.split('=')[1];
        if (value) {
          // Create hash for tracking without exposing the value
          const hash = crypto.createHash('sha256').update(value).digest('hex');
          return hash;
        }
      }
    }
    return null;
  }

  // Create rotation tracking spreadsheet data (safe format)
  createRotationSpreadsheet(envContent) {
    const rotationItems = this.identifyRotationNeeded(envContent);
    const spreadsheetData = [
      ['Variable Name', 'Rotation Status', 'Last Rotated', 'Tracking Hash', 'Priority']
    ];

    rotationItems.forEach(variable => {
      const hash = this.generateTrackingHash(variable, envContent);
      spreadsheetData.push([
        variable,
        'Pending',
        'Never',
        hash ? `${hash.substring(0, 8)}...` : 'N/A',
        this.getRotationPriority(variable)
      ]);
    });

    return spreadsheetData;
  }

  getRotationPriority(variableName) {
    if (variableName.includes('DATABASE') || variableName.includes('MASTER')) {
      return 'CRITICAL';
    }
    if (variableName.includes('API') || variableName.includes('SECRET')) {
      return 'HIGH';
    }
