// Secure secrets management with validation and fallbacks
const Joi = require('joi');

// Validation schema for environment variables
const envVarsSchema = Joi.object({
  NODE_ENV: Joi.string()
    .valid('development', 'production', 'test', 'staging')
    .default('development'),

  PORT: Joi.number()
    .default(3000),

  ADMIN_USER: Joi.string()
    .required()
    .description('Admin username for basic auth'),

  ADMIN_PASSWORD: Joi.string()
    .required()
    .min(12)
    .description('Admin password for basic auth'),

  SESSION_SECRET: Joi.string()
    .required()
    .min(32)
    .description('Session secret key'),

  JWT_SECRET: Joi.string()
    .required()
    .min(32)
    .description('JWT secret key'),

  // External services (optional but validated if present)
  DATABASE_URL: Joi.string()
    .uri()
    .optional(),

  AWS_ACCESS_KEY_ID: Joi.string()
    .optional(),

  AWS_SECRET_ACCESS_KEY: Joi.string()
    .optional(),
})
.unknown();

const { value: envVars, error } = envVarsSchema.validate(process.env);

if (error) {
  throw new Error(`Config validation error: ${error.message}`);
}

module.exports = {
  env: envVars.NODE_ENV,
  port: envVars.PORT,

  auth: {
    adminUser: envVars.ADMIN_USER,
    adminPassword: envVars.ADMIN_PASSWORD,
  },

  secrets: {
    session: envVars.SESSION_SECRET,
    jwt: envVars.JWT_SECRET,
  },

  // External services
  databaseUrl: envVars.DATABASE_URL,
  aws: {
    accessKeyId: envVars.AWS_ACCESS_KEY_ID,
    secretAccessKey: envVars.AWS_SECRET_ACCESS_KEY,
  },

  // Optional: Add method to mask secrets in logs
  maskSecret: (secret) => {
    if (!secret) return '***';
    return secret.length <= 4 
      ? '***' 
      : `${secret.substring(0, 2)}***${secret.substring(secret.length - 2)}`;
  }
};

