        }
    }
});

console.log('\n📊 Audit Summary:');
console.log('Run the following commands for additional security checks:');
console.log('  npm audit --audit-level=moderate');
console.log('  npx nodejsscan app.js');
console.log('  npx safety-ci check');

console.log('\n🔧 Recommended Actions:');
console.log('1. Install missing security dependencies: npm install helmet cors express-rate-limit express-validator express-sanitizer bcryptjs');
console.log('2. Copy .env.example to .env and configure properly');
console.log('3. Run npm audit to check for vulnerable packages');
console.log('4. Consider using app_secure.js as your main application file');

console.log('\n✅ Security audit completed. Review findings and take appropriate actions.');

