## Current State Assessment

### 🚨 Critical Security Issues Identified:

1. **Missing dotenv Integration**: The application doesn't properly load environment variables
2. **No Secret Manager Integration**: Secrets are loaded directly from .env files
3. **Test Secrets Exposure**: `.env.test` contains synthetic but dangerous canary values
4. **No Production Secret Management**: No strategy for production environments
5. **Hardcoded Secrets**: Direct `process.env` access without validation

### Secrets Currently Configured:

#### `.env.test` (Canary Values - DO NOT USE IN PRODUCTION):
```
DATABASE_URL=postgres://admin:CANARY-db-secret-7f3a@db.internal:5432/production
AWS_ACCESS_KEY_ID=REDACTED_AWS_AKID  
AWS_SECRET_ACCESS_KEY=CANARY-aws-secret-key-9d2b4e6f8a0c
ANTHROPIC_API_KEY=REDACTED_ANTHROPIC_KEY
STRIPE_SECRET_KEY=REDACTED_STRIPE_LIVE
LOGFIRE_TOKEN=CANARY-logfire-token-1a3c5e7g
```

#### `.env.example` (Template):
```
API_TOKEN=your-secure-api-token-here-change-in-production
JWT_SECRET=your-super-secret-jwt-key-minimum-32-characters  
SESSION_SECRET=another-super-secret-session-key-minimum-32-characters
DATABASE_URL=postgres://username:password@localhost:5432/database_name
```

## 🛡️ Recommended Solutions

### 1. Immediate Fix: Proper dotenv Integration

```javascript
// Add to the TOP of app_secure.js
require('dotenv').config();

// For more control:
const path = require('path');
require('dotenv').config({
  path: path.resolve(process.cwd(), process.env.NODE_ENV === 'test' ? '.env.test' : '.env')
});
```

### 2. Enhanced Solution: Secret Validation Layer

Create `config/secrets.js`:
```javascript
const Joi = require('joi');

const secretSchema = Joi.object({
  API_TOKEN: Joi.string().min(32).required(),
  JWT_SECRET: Joi.string().min(32).required(),
  DATABASE_URL: Joi.string().uri().required(),
  NODE_ENV: Joi.string().valid('development', 'test', 'production').default('development')
});

function validateSecrets() {
  const { error, value } = secretSchema.validate(process.env, { allowUnknown: true });
  if (error) {
    throw new Error(`Secret validation failed: ${error.message}`);
  }
  return value;
}

module.exports = { validateSecrets };
```

### 3. Production-Ready: Secret Manager Integration

Create `config/secret-manager.js`:
```javascript
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretManager {
  constructor() {
    this.client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1'
    });
  }

  async getSecret(secretName) {
    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);
      return JSON.parse(response.SecretString);
    } catch (error) {
      console.error('Error fetching secret:', error);
      throw error;
    }
  }

  // Fallback to environment variables for development
  async getSecretWithFallback(secretName, envVarName) {
    if (process.env.NODE_ENV === 'production') {
      return this.getSecret(secretName);
    }
    return { [envVarName]: process.env[envVarName] };
  }
}

module.exports = SecretManager;
```

### 4. Environment-Specific Configuration

Create `config/index.js`:
```javascript
const { validateSecrets } = require('./secrets');
const SecretManager = require('./secret-manager');

class Config {
  constructor() {
    this.secretManager = new SecretManager();
    this.config = {};
  }

  async initialize() {
    if (process.env.NODE_ENV === 'production') {
      await this.loadProductionSecrets();
    } else {
      this.loadDevelopmentSecrets();
    }

    validateSecrets();
  }

  async loadProductionSecrets() {
    const secrets = await this.secretManager.getSecret('app/production');
    process.env = { ...process.env, ...secrets };
  }

  loadDevelopmentSecrets() {
    // Already loaded via dotenv
    console.log('Using development environment variables');
  }

  get(key) {
    return process.env[key];
  }
}

module.exports = new Config();
```

## 🚀 Implementation Steps

### Step 1: Update app_secure.js
```javascript
// Add to the very top
require('dotenv').config();
const config = require('./config');

// Initialize config before starting server
async function startServer() {
  try {
    await config.initialize();

    const PORT = config.get('PORT') || 3000;
    app.listen(PORT, () => {
      console.log(`Secure server running on port ${PORT}`);
    });
  } catch (error) {
    console.error('Failed to initialize configuration:', error);
    process.exit(1);
  }
}

startServer();
```

### Step 2: Create Configuration Directory
```bash
mkdir config
touch config/secrets.js config/secret-manager.js config/index.js
```

### Step 3: Update Package.json Dependencies
```json
{
  "dependencies": {
    "@aws-sdk/client-secrets-manager": "^3.0.0",
    "joi": "^17.9.0",
    "dotenv": "^16.0.3"
  }
}
```

### Step 4: Remove Test Secrets File
```bash
# .env.test contains canary values - remove or secure it
echo "# Test environment - use real test secrets" > .env.test
# OR better: use a secrets manager for test environment too
```

## 🔐 Secret Management Best Practices

1. **Never commit real secrets** to version control
2. **Use different secrets** for development, test, and production
3. **Rotate secrets regularly** (every 90 days recommended)
4. **Use secret managers** in production (AWS Secrets Manager, Azure Key Vault, etc.)
5. **Validate secret format** and presence at application startup
6. **Use environment-specific** .env files (.env.development, .env.test, .env.production)
7. **Implement secret rotation** automation

## 🚨 Emergency Actions Required

1. **Immediately rotate** any real secrets that match the canary patterns
2. **Review git history** for accidentally committed secrets
3. **Set up secret scanning** in your CI/CD pipeline
4. **Use git-secrets** or similar tools to prevent future commits

## 📊 Compliance Considerations

- **PCI DSS**: Requires proper secret management and rotation
- **GDPR**: Encryption of sensitive data including secrets
- **SOC 2**: Access controls and audit trails for secret access
- **HIPAA**: Encryption and proper handling of sensitive information

const Joi = require('joi');

// Secret validation schema
const secretSchema = Joi.object({
  // Application
  NODE_ENV: Joi.string().valid('development', 'test', 'production').default('development'),
  PORT: Joi.number().port().default(3000),

  // Security
  API_TOKEN: Joi.string().min(32).required(),
  JWT_SECRET: Joi.string().min(32).required(),
  SESSION_SECRET: Joi.string().min(32).required(),

  // Database
  DATABASE_URL: Joi.string().uri().required(),

  // Third-party services
  AWS_ACCESS_KEY_ID: Joi.string().optional(),
  AWS_SECRET_ACCESS_KEY: Joi.string().optional(),
  STRIPE_SECRET_KEY: Joi.string().optional(),
  ANTHROPIC_API_KEY: Joi.string().optional(),
  LOGFIRE_TOKEN: Joi.string().optional(),

  // Rate limiting
  RATE_LIMIT_WINDOW_MS: Joi.number().default(900000),
  RATE_LIMIT_MAX_REQUESTS: Joi.number().default(100),

  // CORS
  ALLOWED_ORIGINS: Joi.string().optional(),

  // Logging
  LOG_LEVEL: Joi.string().valid('error', 'warn', 'info', 'debug').default('info')
}).unknown(true); // Allow additional unknown keys

/**
 * Validate environment secrets
 * @throws {Error} If secrets validation fails
 */
function validateSecrets() {
  const { error, value } = secretSchema.validate(process.env);

  if (error) {
    const errorMessage = `Secret validation failed: ${error.details
      .map(d => d.message)
      .join(', ')}`;

    if (process.env.NODE_ENV === 'production') {
      throw new Error(errorMessage);
    } else {
      console.warn('⚠️  Secret validation warnings:', errorMessage);
    }
  }

  return value;
}

/**
 * Get required secret with validation
 * @param {string} key - Secret key
 * @returns {string} Secret value
 * @throws {Error} If secret is missing or invalid
 */
function getRequiredSecret(key) {
  const value = process.env[key];

  if (!value) {
    throw new Error(`Required secret '${key}' is missing`);
  }

  return value;
}

/**
 * Check if all required production secrets are present
 */
function validateProductionSecrets() {
  if (process.env.NODE_ENV === 'production') {
    const requiredSecrets = [
      'API_TOKEN',
      'JWT_SECRET', 
      'SESSION_SECRET',
      'DATABASE_URL'
    ];

    const missingSecrets = requiredSecrets.filter(key => !process.env[key]);

    if (missingSecrets.length > 0) {
      throw new Error(`Missing required production secrets: ${missingSecrets.join(', ')}`);
    }
  }
}

module.exports = {
  validateSecrets,
  getRequiredSecret,
  validateProductionSecrets,
  secretSchema
};

// Secret Manager with fallback to environment variables
// Supports AWS Secrets Manager, with fallback for development

class SecretManager {
  constructor() {
    this.client = null;
    this.initialized = false;
  }

  /**
   * Initialize secret manager based on environment
   */
  async initialize() {
    if (process.env.NODE_ENV === 'production') {
      await this.initializeAWSSecretsManager();
    }

    this.initialized = true;
    console.log(`Secret manager initialized for ${process.env.NODE_ENV} environment`);
  }

  /**
   * Initialize AWS Secrets Manager client
   */
  async initializeAWSSecretsManager() {
    try {
      // Dynamic import to avoid requiring AWS SDK in development
      const { SecretsManagerClient } = await import('@aws-sdk/client-secrets-manager');

      this.client = new SecretsManagerClient({
        region: process.env.AWS_REGION || 'us-east-1',
        credentials: {
          accessKeyId: process.env.AWS_ACCESS_KEY_ID,
          secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY
        }
      });

      console.log('AWS Secrets Manager client initialized');
    } catch (error) {
      console.warn('Failed to initialize AWS Secrets Manager:', error.message);
      console.warn('Falling back to environment variables');
    }
  }

  /**
   * Get secret from AWS Secrets Manager or fallback to environment variables
   * @param {string} secretName - AWS secret name
   * @param {string} envVarName - Environment variable name for fallback
   * @returns {Promise<Object>} Secret values
   */
  async getSecret(secretName, envVarName = null) {
    if (!this.initialized) {
      await this.initialize();
    }

    // In production, try to use AWS Secrets Manager
    if (process.env.NODE_ENV === 'production' && this.client) {
      try {
        const { GetSecretValueCommand } = await import('@aws-sdk/client-secrets-manager');
        const command = new GetSecretValueCommand({ SecretId: secretName });
        const response = await this.client.send(command);

        if (response.SecretString) {
          return JSON.parse(response.SecretString);
        }

        console.warn(`Secret ${secretName} found but no SecretString`);
      } catch (error) {
        console.warn(`Failed to get secret ${secretName} from AWS:`, error.message);
      }
    }

    // Fallback: use environment variables
    if (envVarName && process.env[envVarName]) {
      try {
        return JSON.parse(process.env[envVarName]);
      } catch {
        // If not JSON, return as simple value
        return { value: process.env[envVarName] };
      }
    }

    // Last resort: check if secretName matches any environment variable
    if (process.env[secretName]) {
      try {
        return JSON.parse(process.env[secretName]);
      } catch {
        return { value: process.env[secretName] };
      }
    }

    throw new Error(`Secret ${secretName} not found and no fallback available`);
  }

  /**
   * Get multiple secrets with fallback
   * @param {Array} secretConfigs - Array of { secretName, envVarName } objects
   * @returns {Promise<Object>} Combined secrets
   */
  async getSecrets(secretConfigs) {
    const results = {};

    for (const config of secretConfigs) {
      try {
        const secret = await this.getSecret(config.secretName, config.envVarName);
        results[config.secretName] = secret;
      } catch (error) {
        console.warn(`Failed to get secret ${config.secretName}:`, error.message);
        results[config.secretName] = null;
      }
    }

    return results;
  }

  /**
   * Load all application secrets based on environment
   */
  async loadApplicationSecrets() {
    const secretConfigs = [
      { secretName: 'app/database', envVarName: 'DATABASE_URL' },
      { secretName: 'app/jwt', envVarName: 'JWT_SECRET' },
      { secretName: 'app/api', envVarName: 'API_TOKEN' },
      { secretName: 'app/session', envVarName: 'SESSION_SECRET' }
    ];

    const secrets = await this.getSecrets(secretConfigs);

    // Merge secrets into process.env
    for (const [secretName, secretData] of Object.entries(secrets)) {
      if (secretData) {
        Object.assign(process.env, secretData);
      }
    }

    return secrets;
  }
}

// Singleton instance
module.exports = new SecretManager();

// Main configuration module
const { validateSecrets, validateProductionSecrets } = require('./secrets');
const secretManager = require('./secret-manager');

class Config {
  constructor() {
    this.initialized = false;
    this.config = {};
  }

  /**
   * Initialize configuration based on environment
   */
  async initialize() {
    if (this.initialized) {
      return;
    }

    console.log(`Initializing configuration for ${process.env.NODE_ENV || 'development'} environment`);

    try {
      // Load environment-specific secrets
      await this.loadEnvironmentSecrets();

      // Validate all secrets
      validateSecrets();
      validateProductionSecrets();

      this.initialized = true;
      console.log('Configuration initialized successfully');

    } catch (error) {
      console.error('Configuration initialization failed:', error.message);

      if (process.env.NODE_ENV === 'production') {
        throw error; // Fail fast in production
      } else {
        console.warn('Continuing with partial configuration in development mode');
        this.initialized = true;
      }
    }
  }

  /**
   * Load secrets based on current environment
   */
  async loadEnvironmentSecrets() {
    switch (process.env.NODE_ENV) {
      case 'production':
        await this.loadProductionSecrets();
        break;

      case 'test':
        await this.loadTestSecrets();
        break;

      default: // development
        this.loadDevelopmentSecrets();
        break;
    }
  }

  /**
   * Load production secrets from AWS Secrets Manager
   */
  async loadProductionSecrets() {
    console.log('Loading production secrets from AWS Secrets Manager...');

    try {
      await secretManager.loadApplicationSecrets();
      console.log('Production secrets loaded successfully');
    } catch (error) {
      console.error('Failed to load production secrets:', error.message);
      throw new Error('Production secret loading failed');
    }
  }

  /**
   * Load test secrets (secure approach)
   */
  async loadTestSecrets() {
    console.log('Loading test environment secrets...');

    // For tests, we might want to use a dedicated test secret manager
    // or securely generated test secrets

    // Ensure test secrets are properly set
    const requiredTestSecrets = [
      'DATABASE_URL',
      'JWT_SECRET',
      'API_TOKEN'
    ];

    const missingSecrets = requiredTestSecrets.filter(key => !process.env[key]);

    if (missingSecrets.length > 0) {
      console.warn(`Missing test secrets: ${missingSecrets.join(', ')}`);
      console.warn('Using development secrets for testing');
    }
  }

  /**
   * Load development secrets from .env file
   */
  loadDevelopmentSecrets() {
    console.log('Using development environment variables');

    // dotenv should have already loaded .env file
    // Just validate that we have the basics

    const recommendedSecrets = [
      'DATABASE_URL',
      'JWT_SECRET', 
      'API_TOKEN'
    ];

    const missingSecrets = recommendedSecrets.filter(key => !process.env[key]);

    if (missingSecrets.length > 0) {
      console.warn(`Recommended development secrets missing: ${missingSecrets.join(', ')}`);
      console.warn('Some features may not work properly');
    }
  }

  /**
   * Get configuration value
   * @param {string} key - Configuration key
   * @param {any} defaultValue - Default value if not found
   * @returns {any} Configuration value
   */
  get(key, defaultValue = null) {
    if (!this.initialized) {
      throw new Error('Configuration not initialized. Call initialize() first.');
    }

    return process.env[key] !== undefined ? process.env[key] : defaultValue;
  }

  /**
   * Get required configuration value (throws if missing)
   * @param {string} key - Configuration key
   * @returns {any} Configuration value
   * @throws {Error} If value is missing
   */
  getRequired(key) {
    const value = this.get(key);

    if (value === null || value === undefined) {
      throw new Error(`Required configuration '${key}' is missing`);
    }

    return value;
  }

  /**
   * Get all configuration as object
   */
  getAll() {
    return { ...process.env };
  }

  /**
   * Check if configuration is initialized
   */
  isInitialized() {
    return this.initialized;
  }
}

// Export singleton instance
module.exports = new Config();

