const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
require('dotenv').config(); // Load environment variables

const app = express();

// Security Middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "'unsafe-inline'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
}));

app.use(cors({
  origin: process.env.NODE_ENV === 'production' 
    ? process.env.FRONTEND_URL 
    : 'http://localhost:3001',
  credentials: true,
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// Body parsing with size limits
app.use(express.json({ limit: '1mb' }));
app.use(express.urlencoded({ extended: true, limit: '1mb' }));

// Remove server header
app.disable('x-powered-by');

// Input validation middleware
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      errors: errors.array(),
      message: 'Validation failed'
    });
  }
  next();
};

// Health endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development'
  });
});

// Sanitized users endpoint with validation
app.get('/users', [
  // Validate and sanitize query parameters
  body('page').optional().isInt({ min: 1 }).toInt(),
  body('limit').optional().isInt({ min: 1, max: 50 }).toInt(),
], validateRequest, (req, res) => {
  // Mock user data - in real app, fetch from secure database
  const users = [
    { 
      id: 1, 
      name: 'Alice', 
      emailHash: 'a4f3b2c1...', // Hashed email instead of plain text
      role: 'user'
    },
    { 
      id: 2, 
      name: 'Bob', 
      emailHash: 'b5e4d3c2...', // Hashed email instead of plain text
      role: 'user'
    },
  ];

  // Filter sensitive data
  const sanitizedUsers = users.map(user => ({
    id: user.id,
    name: user.name,
    role: user.role
    // emailHash only included if user has permission
  }));

  res.json(sanitizedUsers);
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err.message);

  // Don't leak error details in production
  const errorResponse = process.env.NODE_ENV === 'production'
