// Secure Secret Management Configuration
// Use AWS Secrets Manager, HashiCorp Vault, or environment variables

const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretManager {
  constructor() {
    this.cache = new Map();
    this.cacheTimeout = 5 * 60 * 1000; // 5 minutes

    // Initialize AWS Secrets Manager client if AWS credentials are available
    this.secretsClient = null;
    if (process.env.AWS_ACCESS_KEY_ID && process.env.AWS_SECRET_ACCESS_KEY) {
      this.secretsClient = new SecretsManagerClient({
        region: process.env.AWS_REGION || 'us-east-1',
      });
    }
  }

  // Get secret from preferred source (Secrets Manager > Environment Variables > Fallback)
  async getSecret(secretName, fallbackValue = null) {
    // Check cache first
    const cached = this.cache.get(secretName);
    if (cached && Date.now() - cached.timestamp < this.cacheTimeout) {
      return cached.value;
    }

    let secretValue = null;

    // Try AWS Secrets Manager first
    if (this.secretsClient) {
      try {
        secretValue = await this.getFromSecretsManager(secretName);
      } catch (error) {
        console.warn(`Failed to get secret from AWS Secrets Manager: ${error.message}`);
      }
    }

    // Fallback to environment variables
    if (!secretValue && process.env[secretName]) {
      secretValue = process.env[secretName];
      console.log(`Using environment variable for ${secretName}`);
    }

    // Use fallback value if provided
    if (!secretValue && fallbackValue !== null) {
      secretValue = fallbackValue;
      console.warn(`Using fallback value for ${secretName}`);
    }

    if (secretValue === null) {
      throw new Error(`Secret ${secretName} not found and no fallback provided`);
    }

    // Cache the value
    this.cache.set(secretName, {
      value: secretValue,
      timestamp: Date.now()
    });

    return secretValue;
  }

  async getFromSecretsManager(secretName) {
    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.secretsClient.send(command);

      if (response.SecretString) {
        return response.SecretString;
      } else if (response.SecretBinary) {
        return Buffer.from(response.SecretBinary, 'base64').toString('utf8');
      }
    } catch (error) {
      console.error(`Error retrieving secret ${secretName} from AWS:`, error);
      throw error;
    }
  }

  // Clear cache (useful for testing)
  clearCache() {
    this.cache.clear();
  }
}

// Singleton instance
const secretManager = new SecretManager();

// Common secret names for reference
const SECRET_NAMES = {
  DATABASE_URL: 'DATABASE_URL',
  JWT_SECRET: 'JWT_SECRET',
  AWS_ACCESS_KEY: 'AWS_ACCESS_KEY_ID',
  AWS_SECRET_KEY: 'AWS_SECRET_ACCESS_KEY',
  STRIPE_SECRET: 'STRIPE_SECRET_KEY',
  API_KEYS: 'API_KEYS' // JSON string of multiple API keys
};

module.exports = { secretManager, SECRET_NAMES };

// Application Configuration with secure secret management
const { secretManager, SECRET_NAMES } = require('./secrets');

// Load configuration with proper secret management
async function loadConfig() {
  try {
    const config = {
      // Environment
      env: process.env.NODE_ENV || 'development',
      port: process.env.PORT || 3000,

      // Secrets - loaded securely
      databaseUrl: await secretManager.getSecret(SECRET_NAMES.DATABASE_URL),
      jwtSecret: await secretManager.getSecret(SECRET_NAMES.JWT_SECRET, 'fallback-jwt-secret-for-dev'),

      // API Configuration
      frontendUrl: process.env.FRONTEND_URL || 'http://localhost:3001',

      // Security Settings
      rateLimit: {
        windowMs: 15 * 60 * 1000, // 15 minutes
        max: process.env.RATE_LIMIT_MAX ? parseInt(process.env.RATE_LIMIT_MAX) : 100
      },

      // Request limits
      requestSizeLimit: process.env.REQUEST_SIZE_LIMIT || '1mb'
    };

    // Validate required configuration
    if (!config.databaseUrl && config.env === 'production') {
      throw new Error('DATABASE_URL is required in production environment');
    }

    console.log(`Configuration loaded for ${config.env} environment`);
    return config;
  } catch (error) {
    console.error('Failed to load configuration:', error);
    throw error;
  }
}

// Export both the load function and the secret manager for direct access
