      id: user.id,
      name: user.name,
      role: user.role
    }));

    res.json(sanitizedUsers);
  });

  // Database status endpoint (would use the secure database connection)
  app.get('/db-status', async (req, res) => {
    try {
      // In a real application, this would test the database connection
      // using the securely loaded DATABASE_URL
      res.json({ 
        status: 'connected',
        database: 'mock-database',
        message: 'Database connection configured with secure credentials'
      });
    } catch (error) {
      res.status(500).json({ 
        status: 'error',
        message: 'Database connection failed',
        error: config.env === 'development' ? error.message : 'Internal error'
      });
    }
  });

  // Error handling middleware
  app.use((err, req, res, next) => {
    console.error('Error:', err.message);

    const errorResponse = config.env === 'production'
      ? { message: 'Internal server error' }
      : { message: err.message, stack: err.stack };

    res.status(500).json(errorResponse);
  });

  // 404 handler
  app.use((req, res) => {
    res.status(404).json({ message: 'Route not found' });
  });

  return { app, config };
}

// Export the create function for testing and server startup
module.exports = { createApp };

